(()=>{const s=document.createElement('style');s.textContent=`.microscope-instruction{position:relative;z-index:6;margin:0 auto 24px;width:max-content;max-width:calc(100% - 32px);padding:10px 18px;border:2px solid #ffffffb8;border-radius:999px;background:#063b78a8;backdrop-filter:blur(10px);color:#fff;text-align:center;font-size:14px;font-weight:900;box-shadow:0 0 18px #00d9ff66}.microscope-lens{position:fixed;z-index:10000;width:min(520px,88vw);height:min(520px,88vw);border-radius:50%;pointer-events:none;opacity:0;overflow:hidden;transform:translate(-50%,-50%) scale(.65);transition:.2s;background:radial-gradient(circle at 38% 34%,#ffffff20 0 7%,transparent 22%),radial-gradient(circle,transparent 62%,#001b3a88 80%,#001020e8 100%);border:8px solid #fff;box-shadow:0 0 0 8px #008cff,0 0 46px #00d9ff,0 0 62px #ff8a0080}.microscope-lens.active{opacity:1;transform:translate(-50%,-50%) scale(1)}.microscope-view{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:70px 56px;text-align:left;color:#fff}.microscope-copy{font-size:clamp(16px,2vw,24px);line-height:1.5;font-weight:700;text-shadow:0 2px 6px #001b3a;max-width:100%;max-height:100%;overflow:hidden;white-space:normal;overflow-wrap:anywhere;transition:transform .2s;transform-origin:center}.microscope-cross-v,.microscope-cross-h{position:absolute;background:#ffffff55;pointer-events:none}.microscope-cross-v{width:1px;height:100%;left:50%}.microscope-cross-h{height:1px;width:100%;top:50%}.microscope-label{position:absolute;left:50%;bottom:6%;transform:translateX(-50%);padding:5px 10px;border-radius:999px;background:#001f45df;color:#fff;font-size:11px;font-weight:900;letter-spacing:1px;white-space:nowrap}.scope-setup{position:fixed;z-index:10005;inset:0;display:none;align-items:center;justify-content:center;padding:20px;background:rgba(0,24,58,.48);backdrop-filter:blur(10px)}.scope-setup.show{display:flex}.scope-setup-card{width:min(520px,92vw);padding:30px;border-radius:26px;text-align:center;color:#fff;background:linear-gradient(135deg,rgba(5,69,140,.9),rgba(0,140,255,.68));border:2px solid rgba(255,255,255,.8);box-shadow:0 0 38px #00d9ff88,0 24px 70px #001a3c99}.scope-setup-card svg{width:145px;filter:drop-shadow(0 0 10px #fff) drop-shadow(0 0 18px #00d9ff)}.scope-setup-card h3{font-size:28px;margin:8px 0 5px}.scope-setup-card p{font-size:14px;margin-bottom:18px;color:#eaf7ff}.mag-options{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.mag-btn{border:2px solid #ffffffaa;border-radius:14px;padding:12px 5px;background:#ffffff16;color:#fff;font-weight:1000;font-size:16px;cursor:pointer}.mag-btn:hover{background:#ff8a00;box-shadow:0 0 18px #fff}.scope-cancel{margin-top:14px;border:0;background:transparent;color:#dff4ff;text-decoration:underline;font-weight:800;cursor:pointer}.lab-glass{position:relative!important;background:linear-gradient(135deg,rgba(255,255,255,.62),rgba(220,244,255,.28))!important;border:1px solid rgba(255,255,255,.88)!important;box-shadow:0 18px 48px rgba(0,72,145,.16),inset 0 1px 0 rgba(255,255,255,.95)!important;backdrop-filter:blur(18px) saturate(145%)!important;-webkit-backdrop-filter:blur(18px) saturate(145%)!important;overflow:hidden}.lab-glass-dark{background:linear-gradient(135deg,rgba(4,65,132,.48),rgba(0,140,255,.18))!important;border:1px solid rgba(255,255,255,.55)!important;backdrop-filter:blur(16px) saturate(145%)!important}.microscope-active,.microscope-active *{-webkit-user-select:none!important;user-select:none!important;-webkit-touch-callout:none!important}.bottom-bible-verse{max-width:900px;margin:42px auto 0;padding:0 20px;text-align:center}.bottom-bible-verse .hero-verse{position:static!important;display:block!important;max-width:900px!important;margin:0 auto!important;padding:22px 28px!important;text-align:center!important;color:#0752ad!important;font-size:clamp(18px,2.4vw,25px)!important;font-weight:900!important;line-height:1.5!important;text-shadow:none!important;border:1px solid rgba(255,255,255,.9)!important;border-radius:20px!important;background:linear-gradient(135deg,rgba(255,255,255,.72),rgba(220,244,255,.38))!important;box-shadow:0 18px 48px rgba(0,72,145,.16)!important;backdrop-filter:blur(18px)!important}@media(max-width:760px){.microscope-instruction{font-size:12px}.microscope-copy{font-size:clamp(14px,4vw,20px)}.microscope-view{padding:64px 42px}.mag-options{grid-template-columns:repeat(2,1fr)}.bottom-bible-verse{margin-top:28px;padding:0}}`;document.head.appendChild(s);document.querySelectorAll('.summary-card,.research-person,.info-card').forEach(e=>e.classList.add('lab-glass'));document.querySelectorAll('.molecule-link').forEach(e=>e.classList.add('lab-glass-dark'));const verse=document.querySelector('.hero-verse'),research=document.querySelector('.research-by'),grid=document.querySelector('.research-grid');if(verse&&research&&!verse.closest('.bottom-bible-verse')){const w=document.createElement('div');w.className='bottom-bible-verse';w.appendChild(verse);if(grid&&grid.parentNode)grid.parentNode.insertBefore(w,grid.nextSibling);else research.appendChild(w)}const hero=document.querySelector('.hero');if(hero&&!document.querySelector('.microscope-instruction')){const note=document.createElement('div');note.className='microscope-instruction lab-glass-dark';note.textContent='Double-click the screen or mouse to enter and leave microscope mode.';hero.insertBefore(note,hero.firstChild)}const lens=document.createElement('div');lens.className='microscope-lens';lens.innerHTML='<div class="microscope-view"><div class="microscope-copy"></div></div><i class="microscope-cross-v"></i><i class="microscope-cross-h"></i><span class="microscope-label">MICROSCOPE MODE</span>';document.body.appendChild(lens);const copy=lens.querySelector('.microscope-copy');const setup=document.createElement('div');setup.className='scope-setup';setup.innerHTML='<div class="scope-setup-card"><svg viewBox="0 0 220 220"><g fill="none" stroke="#fff" stroke-width="9" stroke-linecap="round"><path d="M94 29h38l8 35-30 7z" fill="#008cff"/><path d="M112 70l-19 44"/><path d="M89 116c18 8 40 4 54-12"/><path d="M132 88c28 14 34 48 20 72"/><path d="M71 165h90"/><circle cx="87" cy="124" r="10" fill="#ff8a00"/></g></svg><h3>Select Magnification</h3><p>Choose a lens before entering microscope mode. The full text block under your pointer will be displayed.</p><div class="mag-options"><button class="mag-btn" data-mag="1">1.25×</button><button class="mag-btn" data-mag="1.08">1.5×</button><button class="mag-btn" data-mag="1.16">2×</button><button class="mag-btn" data-mag="1.26">3×</button></div><button class="scope-cancel">Cancel</button></div>';document.body.appendChild(setup);let active=false,lastEvent=null,lastTap=0;const selector='h1,h2,h3,p,.eyebrow,.kicker,.credit-label,.institution,.hero-verse,.molecule-link,.paper-button,.comic-panel span,.bottom-band,footer';function update(e){lastEvent=e;if(!active)return;lens.style.left=e.clientX+'px';lens.style.top=e.clientY+'px';const el=document.elementFromPoint(e.clientX,e.clientY),valid=el&&el.closest(selector);copy.textContent=valid&&valid.textContent?valid.textContent.trim():''}function clearSel(){const x=window.getSelection&&window.getSelection();if(x&&x.removeAllRanges)x.removeAllRanges()}function enter(m){active=true;setup.classList.remove('show');copy.style.transform='scale('+m+')';lens.classList.add('active');document.body.classList.add('microscope-active');clearSel();if(lastEvent)update(lastEvent)}function exit(){active=false;lens.classList.remove('active');document.body.classList.remove('microscope-active');copy.textContent='';clearSel()}function toggle(e){if(e.target.closest('a,button,.info-card,.scope-setup'))return;lastEvent=e;if(active)exit();else setup.classList.add('show')}document.addEventListener('dblclick',e=>{e.preventDefault();toggle(e)});document.addEventListener('touchend',e=>{if(e.changedTouches.length!==1)return;const now=Date.now(),t=e.changedTouches[0];if(now-lastTap<350){e.preventDefault();toggle({target:e.target,clientX:t.clientX,clientY:t.clientY})}lastTap=now},{passive:false});setup.querySelectorAll('.mag-btn').forEach(b=>b.addEventListener('click',()=>enter(b.dataset.mag)));setup.querySelector('.scope-cancel').addEventListener('click',()=>setup.classList.remove('show'));document.addEventListener('selectstart',e=>{if(active)e.preventDefault()});document.addEventListener('copy',e=>{if(active)e.preventDefault()});document.addEventListener('cut',e=>{if(active)e.preventDefault()});addEventListener('pointermove',update,{passive:true})})();